-- State transitions declared for OAuthProvider (shadow: an undeclared move raises a WARNING).
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION sapiens.oauth_providers_status_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."status" IS DISTINCT FROM OLD."status" AND NOT (
           (COALESCE(OLD."status"::text, ''), COALESCE(NEW."status"::text, '')) IN (('active', 'inactive'))
       ) THEN
        RAISE WARNING 'state_transition_not_declared: oauth_providers.status % -> %', OLD."status", NEW."status";
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS oauth_providers_status_transition_check ON sapiens.oauth_providers;
CREATE TRIGGER oauth_providers_status_transition_check
    BEFORE UPDATE OF "status" ON sapiens.oauth_providers
    FOR EACH ROW EXECUTE FUNCTION sapiens.oauth_providers_status_transition_check();
